-- ── Triggers (public-schema tables only) ──────────────────────────────
CREATE TRIGGER trg_conversations_updated BEFORE UPDATE ON public.ziko_ai_conversations FOR EACH ROW EXECUTE FUNCTION ziko_handle_updated_at();
CREATE TRIGGER trg_credit_transaction_balance_after BEFORE INSERT ON public.ziko_ai_credit_transactions FOR EACH ROW EXECUTE FUNCTION ziko_set_credit_transaction_balance_after();
CREATE TRIGGER trg_ai_imports_updated BEFORE UPDATE ON public.ziko_ai_imports FOR EACH ROW EXECUTE FUNCTION ziko_handle_updated_at();
