CREATE TRIGGER trg_coach_branding_updated BEFORE UPDATE ON public.ziko_coach_branding FOR EACH ROW EXECUTE FUNCTION ziko_handle_updated_at();
CREATE TRIGGER trg_coach_profiles_updated BEFORE UPDATE ON public.ziko_coach_profiles FOR EACH ROW EXECUTE FUNCTION ziko_handle_updated_at();
CREATE TRIGGER trg_ensure_community_stats AFTER INSERT ON public.ziko_friendships FOR EACH ROW EXECUTE FUNCTION ziko_ensure_community_stats();
CREATE TRIGGER trg_persona_updated BEFORE UPDATE ON public.ziko_persona_settings FOR EACH ROW EXECUTE FUNCTION ziko_handle_updated_at();
CREATE TRIGGER update_plugin_reviews_updated_at BEFORE UPDATE ON public.ziko_plugin_reviews FOR EACH ROW EXECUTE FUNCTION ziko_update_updated_at_column();
CREATE TRIGGER trg_post_comments_count AFTER INSERT OR DELETE ON public.ziko_post_comments FOR EACH ROW EXECUTE FUNCTION ziko_update_post_comments_count();
CREATE TRIGGER trg_post_likes_count AFTER INSERT OR DELETE ON public.ziko_post_likes FOR EACH ROW EXECUTE FUNCTION ziko_update_post_likes_count();
CREATE TRIGGER trg_user_ai_credits_updated BEFORE UPDATE ON public.ziko_user_ai_credits FOR EACH ROW EXECUTE FUNCTION ziko_handle_updated_at();
CREATE TRIGGER push_user_xp_level_up AFTER UPDATE ON public.ziko_user_gamification FOR EACH ROW EXECUTE FUNCTION supabase_functions.http_request('https://api.ziko-app.com/push-events/supabase', 'POST', '{"Content-type":"application/json","X-Webhook-Secret":"{{X_WEBHOOK_SECRET}}"}', '{}', '5000');
CREATE TRIGGER trg_unlock_default_theme AFTER INSERT ON public.ziko_user_profiles FOR EACH ROW EXECUTE FUNCTION ziko_unlock_default_theme();
CREATE TRIGGER trg_user_profiles_updated BEFORE UPDATE ON public.ziko_user_profiles FOR EACH ROW EXECUTE FUNCTION ziko_handle_updated_at();
CREATE TRIGGER trg_programs_updated BEFORE UPDATE ON public.ziko_workout_programs FOR EACH ROW EXECUTE FUNCTION ziko_handle_updated_at();
CREATE TRIGGER push_workout_session_end AFTER UPDATE ON public.ziko_workout_sessions FOR EACH ROW EXECUTE FUNCTION supabase_functions.http_request('https://api.ziko-app.com/push-events/supabase', 'POST', '{"Content-type":"application/json","X-Webhook-Secret":"{{X_WEBHOOK_SECRET}}"}', '{}', '5000');

-- ── RLS policies that call a ziko_ function (need the function to exist) ────
CREATE POLICY "body_measurements_coach_read" ON public.ziko_body_measurements AS PERMISSIVE FOR SELECT USING (((auth.uid() = user_id) OR ziko_is_coach_of(auth.uid(), user_id)));
CREATE POLICY "cardio_sessions_coach_read" ON public.ziko_cardio_sessions AS PERMISSIVE FOR SELECT USING (((auth.uid() = user_id) OR ziko_is_coach_of(auth.uid(), user_id)));
CREATE POLICY "coach_branding_athlete_read" ON public.ziko_coach_branding AS PERMISSIVE FOR SELECT USING (ziko_is_coach_of(coach_id, auth.uid()));
CREATE POLICY "coach_client_videos_coach_read" ON public.ziko_coach_client_videos AS PERMISSIVE FOR SELECT USING (ziko_is_coach_of(auth.uid(), athlete_id));
CREATE POLICY "form_instances_coach" ON public.ziko_form_instances AS PERMISSIVE FOR SELECT USING ((ziko_is_coach_of(auth.uid(), athlete_id) OR (EXISTS ( SELECT 1
   FROM ziko_coach_forms cf
  WHERE ((cf.id = ziko_form_instances.form_id) AND (cf.coach_id = auth.uid()))))));
CREATE POLICY "form_responses_coach_read" ON public.ziko_form_responses AS PERMISSIVE FOR SELECT USING (ziko_is_coach_of(auth.uid(), athlete_id));
CREATE POLICY "habit_logs_coach_read" ON public.ziko_habit_logs AS PERMISSIVE FOR SELECT USING (((auth.uid() = user_id) OR ziko_is_coach_of(auth.uid(), user_id)));
CREATE POLICY "habits_coach_read" ON public.ziko_habits AS PERMISSIVE FOR SELECT USING (((auth.uid() = user_id) OR ziko_is_coach_of(auth.uid(), user_id)));
CREATE POLICY "hydration_logs_coach_read" ON public.ziko_hydration_logs AS PERMISSIVE FOR SELECT USING (((auth.uid() = user_id) OR ziko_is_coach_of(auth.uid(), user_id)));
CREATE POLICY "journal_entries_coach_read" ON public.ziko_journal_entries AS PERMISSIVE FOR SELECT USING (((auth.uid() = user_id) OR ziko_is_coach_of(auth.uid(), user_id)));
CREATE POLICY "nutrition_logs_coach_read" ON public.ziko_nutrition_logs AS PERMISSIVE FOR SELECT USING (((auth.uid() = user_id) OR ziko_is_coach_of(auth.uid(), user_id)));
CREATE POLICY "program_exercises_coach_read" ON public.ziko_program_exercises AS PERMISSIVE FOR SELECT USING ((workout_id IN ( SELECT pw.id
   FROM (ziko_program_workouts pw
     JOIN ziko_workout_programs wp ON ((wp.id = pw.program_id)))
  WHERE ziko_is_coach_of(auth.uid(), wp.user_id))));
CREATE POLICY "program_workouts_coach_read" ON public.ziko_program_workouts AS PERMISSIVE FOR SELECT USING ((program_id IN ( SELECT ziko_workout_programs.id
   FROM ziko_workout_programs
  WHERE ziko_is_coach_of(auth.uid(), ziko_workout_programs.user_id))));
CREATE POLICY "session_sets_coach_read" ON public.ziko_session_sets AS PERMISSIVE FOR SELECT USING ((EXISTS ( SELECT 1
   FROM ziko_workout_sessions ws
  WHERE ((ws.id = ziko_session_sets.session_id) AND ((auth.uid() = ws.user_id) OR ziko_is_coach_of(auth.uid(), ws.user_id))))));
CREATE POLICY "sleep_logs_coach_read" ON public.ziko_sleep_logs AS PERMISSIVE FOR SELECT USING (((auth.uid() = user_id) OR ziko_is_coach_of(auth.uid(), user_id)));
CREATE POLICY "stretching_logs_coach_read" ON public.ziko_stretching_logs AS PERMISSIVE FOR SELECT USING (((auth.uid() = user_id) OR ziko_is_coach_of(auth.uid(), user_id)));
CREATE POLICY "user_profiles_coach_read" ON public.ziko_user_profiles AS PERMISSIVE FOR SELECT USING (((auth.uid() = id) OR ziko_is_coach_of(auth.uid(), id)));
CREATE POLICY "workout_programs_client_coach_update" ON public.ziko_workout_programs AS PERMISSIVE FOR UPDATE USING (ziko_is_coach_of(auth.uid(), user_id)) WITH CHECK (ziko_is_coach_of(auth.uid(), user_id));
CREATE POLICY "workout_programs_client_own_coach_read" ON public.ziko_workout_programs AS PERMISSIVE FOR SELECT USING (ziko_is_coach_of(auth.uid(), user_id));
CREATE POLICY "workout_programs_coach_assign" ON public.ziko_workout_programs AS PERMISSIVE FOR INSERT WITH CHECK (((created_by_coach_id = auth.uid()) AND (assigned_to_user_id IS NOT NULL) AND ziko_is_coach_of(auth.uid(), assigned_to_user_id)));
CREATE POLICY "workout_programs_coach_read" ON public.ziko_workout_programs AS PERMISSIVE FOR SELECT USING (((auth.uid() = user_id) OR ((assigned_to_user_id IS NOT NULL) AND ziko_is_coach_of(auth.uid(), assigned_to_user_id)) OR ((is_template = true) AND (created_by_coach_id IS NULL))));
CREATE POLICY "workout_sessions_coach_read" ON public.ziko_workout_sessions AS PERMISSIVE FOR SELECT USING (((auth.uid() = user_id) OR ziko_is_coach_of(auth.uid(), user_id)));

